create table public.notifications (
  id bigint generated by default as identity primary key, user_id uuid not null references public.profiles(id) on delete cascade, club_id bigint references public.clubs(id) on delete cascade,
  type varchar(60) not null, title varchar(200) not null, body text, data jsonb not null default '{}'::jsonb, read_at timestamptz, created_at timestamptz not null default now()
);
create table public.funds (
  id bigint generated by default as identity primary key, club_id bigint not null references public.clubs(id) on delete restrict,
  name varchar(120) not null, currency char(3) not null default 'VND', opening_balance numeric(20,2) not null default 0, is_active boolean not null default true,
  created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (club_id,name)
);
create table public.financial_periods (
  id bigint generated by default as identity primary key, club_id bigint not null references public.clubs(id) on delete restrict,
  starts_on date not null, ends_on date not null, closed_at timestamptz, closed_by uuid references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (ends_on >= starts_on), unique (club_id,starts_on,ends_on)
);
create table public.transaction_approvals (
  id bigint generated by default as identity primary key, club_id bigint not null, finance_transaction_id bigint not null, status varchar(20) not null default 'pending' check (status in ('pending','approved','rejected','cancelled')),
  requested_by uuid not null references public.profiles(id), decided_by uuid references public.profiles(id), decision_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (club_id,finance_transaction_id), foreign key (club_id,finance_transaction_id) references public.finance_transactions(club_id,id) on delete restrict
);
create table public.payments (
  id bigint generated by default as identity primary key, club_id bigint not null references public.clubs(id) on delete restrict, player_id bigint, amount numeric(20,2) not null check (amount > 0), paid_on date not null, status varchar(20) not null default 'posted' check (status in ('pending','posted','voided')), external_ref varchar(160), created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (club_id,id), foreign key (club_id,player_id) references public.player_profiles(club_id,id) on delete restrict
);
create table public.payment_allocations (
  id bigint generated by default as identity primary key, club_id bigint not null, payment_id bigint not null, dues_entry_id bigint, amount numeric(20,2) not null check (amount > 0), created_at timestamptz not null default now(),
  foreign key (club_id,payment_id) references public.payments(club_id,id) on delete restrict, foreign key (dues_entry_id) references public.team_dues_entries(id) on delete restrict
);
create table public.import_jobs (
  id uuid primary key default gen_random_uuid(), club_id bigint not null references public.clubs(id) on delete restrict, created_by uuid not null references public.profiles(id), kind varchar(60) not null, status varchar(20) not null default 'pending' check (status in ('pending','processing','completed','failed','cancelled')), total_rows integer not null default 0, processed_rows integer not null default 0, error_count integer not null default 0, errors jsonb not null default '[]'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table public.club_public_settings (
  club_id bigint primary key references public.clubs(id) on delete cascade, public_slug varchar(160) unique, is_published boolean not null default false, headline varchar(255), content jsonb not null default '{}'::jsonb, updated_by uuid references public.profiles(id), updated_at timestamptz not null default now()
);

create index club_members_user_status_idx on public.club_members(user_id, status);
create index audit_logs_club_created_idx on public.audit_logs(club_id, created_at);
create index finance_transactions_club_date_idx on public.finance_transactions(club_id, occurred_on);
create index player_profiles_club_status_name_idx on public.player_profiles(club_id, status, full_name);
create index team_players_club_team_idx on public.team_players(club_id, team_id);
create index inventory_items_club_archived_name_idx on public.inventory_items(club_id, archived, name);
create index club_matches_club_date_idx on public.club_matches(club_id, match_date);
create index notifications_user_unread_idx on public.notifications(user_id, read_at, created_at desc);
create index payments_club_date_idx on public.payments(club_id, paid_on);
create index import_jobs_club_created_idx on public.import_jobs(club_id, created_at desc);

create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;
do $$ declare t text; begin foreach t in array array['profiles','clubs','club_members','teams','player_profiles','club_invitations','audit_logs','finance_transactions','team_dues_rates','team_membership_periods','team_dues_entries','team_dues_adjustments','club_board_members','board_membership_periods','board_dues_rates','shared_board_dues_rates','club_celebrations','team_trainings','club_awards','planned_expenses','friendly_invitations','club_matches','match_lineups','match_attendances','player_match_stats','match_cost_splits','match_cost_receivables','inventory_items','inventory_assignments','inventory_movements','club_polls','club_poll_options','club_poll_electors','club_poll_votes','recruitment_posts','recruitment_applications','sponsors','sponsorships','sponsorship_receipts','discipline_cases','board_tasks','seasons','club_events','funds','financial_periods','transaction_approvals','payments','import_jobs','club_public_settings'] loop execute format('drop trigger if exists set_updated_at on public.%I; create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()', t, t); end loop; end $$;

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles(id, name, email) values (new.id, coalesce(new.raw_user_meta_data->>'name',''), lower(new.email)) on conflict (id) do update set email = excluded.email; return new; end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

create or replace function public.is_active_member(p_club_id bigint, p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.club_members where club_id = p_club_id and user_id = p_user_id and status = 'active') $$;
create or replace function public.club_role(p_club_id bigint, p_user_id uuid default auth.uid()) returns public.club_role language sql stable security definer set search_path = public as $$ select role from public.club_members where club_id = p_club_id and user_id = p_user_id and status = 'active' limit 1 $$;
create or replace function public.can_manage_roster(p_club_id bigint, p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path = public as $$ select public.club_role(p_club_id,p_user_id) in ('owner','co_owner','general_manager','hr_manager','sporting_manager') $$;
create or replace function public.can_manage_club(p_club_id bigint, p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path = public as $$ select public.club_role(p_club_id,p_user_id) in ('owner','co_owner','general_manager') $$;
create or replace function public.can_view_finance(p_club_id bigint, p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.club_members m where m.club_id=p_club_id and m.user_id=p_user_id and m.status='active' and (m.role='owner' or m.title in ('Chủ nhiệm CLB','Phó chủ nhiệm CLB','Thủ quỹ','HLV'))) $$;
create or replace function public.can_manage_finance(p_club_id bigint, p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.club_members m where m.club_id=p_club_id and m.user_id=p_user_id and m.status='active' and (m.role='owner' or m.title='Thủ quỹ')) $$;
create or replace function public.can_view_inventory(p_club_id bigint, p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path = public as $$ select public.club_role(p_club_id,p_user_id) in ('owner','co_owner','general_manager','equipment_manager') $$;
create or replace function public.can_manage_inventory(p_club_id bigint, p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path = public as $$ select public.can_view_inventory(p_club_id,p_user_id) and exists(select 1 from public.clubs where id=p_club_id and status='active') $$;
create or replace function public.can_view_activities(p_club_id bigint, p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path = public as $$ select public.can_manage_roster(p_club_id,p_user_id) or exists(select 1 from public.club_members where club_id=p_club_id and user_id=p_user_id and status='active' and title='Phó chủ nhiệm CLB') $$;
create or replace function public.can_manage_activities(p_club_id bigint, p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.clubs where id=p_club_id and status='active') and (public.club_role(p_club_id,p_user_id) in ('owner','co_owner','general_manager','hr_manager','sporting_manager') or exists(select 1 from public.club_members where club_id=p_club_id and user_id=p_user_id and status='active' and title='Phó chủ nhiệm CLB')) $$;
create or replace function public.can_manage_people(p_club_id bigint, p_user_id uuid default auth.uid()) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.clubs where id=p_club_id and status='active') and public.club_role(p_club_id,p_user_id) in ('owner','co_owner','general_manager','hr_manager') $$;

create or replace function public.create_club(p_name text, p_description text default null, p_city text default null, p_home_ground text default null, p_formats jsonb default '["7"]'::jsonb) returns public.clubs language plpgsql security definer set search_path = public as $$ declare c public.clubs; slug_base text; begin if auth.uid() is null then raise exception 'not_authenticated'; end if; if jsonb_typeof(p_formats) <> 'array' or jsonb_array_length(p_formats)=0 then raise exception 'invalid_formats'; end if; slug_base := regexp_replace(lower(coalesce(nullif(trim(p_name),''),'club')), '[^a-z0-9]+', '-', 'g'); insert into public.clubs(name,description,city,home_ground,format,formats,slug) values(trim(p_name),p_description,p_city,p_home_ground,p_formats->>0,p_formats,slug_base||'-'||substr(replace(gen_random_uuid()::text,'-',''),1,12)) returning * into c; insert into public.club_members(club_id,user_id,role,status) values(c.id,auth.uid(),'owner','active'); insert into public.audit_logs(club_id,actor_id,action,subject_type,subject_id) values(c.id,auth.uid(),'club.created','Club',c.id); return c; end $$;

create or replace function public.accept_club_invitation(p_token text) returns public.clubs language plpgsql security definer set search_path = public as $$ declare i public.club_invitations; c public.clubs; begin select * into i from public.club_invitations where token_hash=encode(extensions.digest(p_token,'sha256'),'hex') for update; if i.id is null or i.accepted_at is not null or i.expires_at < now() or lower(i.email) <> lower((select email from public.profiles where id=auth.uid())) then raise exception 'invalid_invitation'; end if; select * into c from public.clubs where id=i.club_id for update; if c.status <> 'active' then raise exception 'inactive_club'; end if; if exists(select 1 from public.club_members where club_id=c.id and user_id=auth.uid()) then raise exception 'already_member'; end if; insert into public.club_members(club_id,user_id,role) values(c.id,auth.uid(),i.role); update public.club_invitations set accepted_at=now() where id=i.id; insert into public.audit_logs(club_id,actor_id,action,subject_type,subject_id) values(c.id,auth.uid(),'invitation.accepted','ClubInvitation',i.id); return c; end $$;

create or replace function public.create_club_invitation(p_club_id bigint,p_email text,p_role public.club_role) returns jsonb language plpgsql security definer set search_path = public as $$
declare token_value text := encode(extensions.gen_random_bytes(32),'hex'); invitation public.club_invitations; actor_role public.club_role := public.club_role(p_club_id); normalized_email text := lower(trim(p_email));
begin
  if p_role='owner' or normalized_email='' or (p_role='co_owner' and actor_role <> 'owner') or (p_role='member' and actor_role not in ('owner','co_owner','general_manager','hr_manager')) or (p_role not in ('co_owner','member') and actor_role not in ('owner','co_owner')) then raise exception 'forbidden_or_invalid'; end if;
  if not exists(select 1 from public.clubs where id=p_club_id and status='active') then raise exception 'inactive_club'; end if;
  if exists(select 1 from public.club_members m join public.profiles p on p.id=m.user_id where m.club_id=p_club_id and m.status='active' and lower(p.email)=normalized_email) then raise exception 'already_member'; end if;
  insert into public.club_invitations(club_id,invited_by,email,role,token_hash,expires_at) values(p_club_id,auth.uid(),normalized_email,p_role,encode(extensions.digest(token_value,'sha256'),'hex'),now()+interval '7 days') on conflict(club_id,email) do update set invited_by=excluded.invited_by,role=excluded.role,token_hash=excluded.token_hash,expires_at=excluded.expires_at,accepted_at=null,updated_at=now() returning * into invitation;
  return jsonb_build_object('id',invitation.id,'email',invitation.email,'role',invitation.role,'token',token_value,'expires_at',invitation.expires_at);
end $$;

create or replace function public.claim_player_profile(p_club_id bigint) returns public.player_profiles language plpgsql security definer set search_path = public as $$
declare row_value public.player_profiles; email_value text := lower((select email from public.profiles where id=auth.uid()));
begin
  if auth.uid() is null or (auth.jwt()->>'email_confirmed_at') is null or not public.is_active_member(p_club_id) then raise exception 'email_not_verified_or_forbidden'; end if;
  select * into row_value from public.player_profiles where club_id=p_club_id and user_id is null and email is not null and lower(email)=email_value for update;
  if row_value.id is null then raise exception 'player_profile_not_found'; end if;
  update public.player_profiles set user_id=auth.uid() where club_id=p_club_id and id=row_value.id returning * into row_value; return row_value;
end $$;

create or replace function public.unlink_player_profile(p_club_id bigint) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.is_active_member(p_club_id) then raise exception 'forbidden'; end if;
  update public.player_profiles set user_id=null where club_id=p_club_id and user_id=auth.uid();
end $$;

create or replace function public.record_finance_transaction(p_club_id bigint, p_type public.finance_type, p_amount numeric, p_occurred_on date, p_description text, p_receipt_path text default null, p_category text default null, p_paid_by text default null, p_notes text default null, p_idempotency_key uuid default null) returns public.finance_transactions language plpgsql security definer set search_path = public as $$ declare r public.finance_transactions; begin if not public.can_manage_finance(p_club_id) then raise exception 'forbidden'; end if; if p_amount <= 0 then raise exception 'invalid_amount'; end if; if p_idempotency_key is not null then select * into r from public.finance_transactions where club_id=p_club_id and idempotency_key=p_idempotency_key; if r.id is not null then return r; end if; end if; perform 1 from public.clubs where id=p_club_id and status='active' for update; if not found then raise exception 'inactive_club'; end if; insert into public.finance_transactions(club_id,created_by,type,amount,occurred_on,description,receipt_path,category,paid_by,notes,idempotency_key) values(p_club_id,auth.uid(),p_type,p_amount,p_occurred_on,trim(p_description),p_receipt_path,p_category,p_paid_by,p_notes,p_idempotency_key) returning * into r; insert into public.audit_logs(club_id,actor_id,action,subject_type,subject_id) values(p_club_id,auth.uid(),'finance.created','FinanceTransaction',r.id); return r; end $$;

create or replace function public.record_inventory_movement(p_club_id bigint,p_item_id bigint,p_type text,p_change integer,p_reason text) returns public.inventory_movements language plpgsql security definer set search_path = public as $$ declare item public.inventory_items; m public.inventory_movements; new_balance integer; begin if not public.can_manage_inventory(p_club_id) then raise exception 'forbidden'; end if; select * into item from public.inventory_items where club_id=p_club_id and id=p_item_id for update; if item.id is null or item.archived then raise exception 'invalid_inventory_item'; end if; new_balance := item.quantity + p_change; if new_balance < 0 then raise exception 'insufficient_inventory'; end if; update public.inventory_items set quantity=new_balance where club_id=p_club_id and id=p_item_id; insert into public.inventory_movements(club_id,inventory_item_id,actor_id,type,change,balance_after,reason) values(p_club_id,p_item_id,auth.uid(),p_type,p_change,new_balance,trim(p_reason)) returning * into m; return m; end $$;

create or replace function public.record_team_dues(p_club_id bigint,p_team_id bigint,p_player_id bigint,p_month date,p_months integer,p_status text) returns jsonb language plpgsql security definer set search_path = public as $$ declare cursor_month date:=date_trunc('month',p_month)::date; n integer:=0; amount_value numeric(20,2); begin if not public.can_manage_finance(p_club_id) or p_months < 1 or p_months > 24 or p_status not in ('paid','exempt','unpaid') then raise exception 'forbidden_or_invalid'; end if; perform 1 from public.teams where club_id=p_club_id and id=p_team_id for update; while n < p_months loop select amount into amount_value from public.team_dues_rates where club_id=p_club_id and team_id=p_team_id and effective_month <= cursor_month order by effective_month desc limit 1; if amount_value is not null then insert into public.team_dues_entries(club_id,team_id,player_id,month,status,amount,created_by) values(p_club_id,p_team_id,p_player_id,cursor_month,p_status,amount_value,auth.uid()) on conflict(team_id,player_id,month) do update set status=excluded.status, amount=excluded.amount, updated_at=now(); end if; cursor_month := (cursor_month + interval '1 month')::date; n:=n+1; end loop; return jsonb_build_object('player_id',p_player_id,'team_id',p_team_id,'months',p_months,'status',p_status); end $$;

create or replace function public.record_player_dues(p_club_id bigint,p_player_id bigint,p_month date,p_months integer,p_status text) returns jsonb language plpgsql security definer set search_path = public as $$
declare cursor_month date := date_trunc('month', p_month)::date; n integer := 0; total_amount numeric := 0; tx_id bigint; team_row record; rate_value numeric;
begin
  if not public.can_manage_finance(p_club_id) or p_months < 1 or p_months > 24 or p_status not in ('paid','exempt') then raise exception 'forbidden_or_invalid'; end if;
  perform 1 from public.clubs where id=p_club_id and status='active' for update;
  while n < p_months loop
    for team_row in select distinct tp.team_id from public.team_players tp where tp.club_id=p_club_id and tp.player_id=p_player_id loop
      select amount into rate_value from public.team_dues_rates where club_id=p_club_id and team_id=team_row.team_id and effective_month <= cursor_month order by effective_month desc limit 1;
      if rate_value is not null and rate_value > 0 and not exists(select 1 from public.team_dues_entries where team_id=team_row.team_id and player_id=p_player_id and month=cursor_month) then total_amount := total_amount + rate_value; end if;
    end loop;
    cursor_month := (cursor_month + interval '1 month')::date; n := n + 1;
  end loop;
  if total_amount = 0 then raise exception 'no_dues_to_record'; end if;
  if p_status = 'paid' then insert into public.finance_transactions(club_id,created_by,type,amount,occurred_on,description) select p_club_id,auth.uid(),'income',total_amount,current_date,'Thu quỹ thành viên '||p_player_id||' từ '||to_char(p_month,'YYYY-MM')||' ('||p_months||' tháng)' returning id into tx_id; end if;
  cursor_month := date_trunc('month', p_month)::date; n := 0;
  while n < p_months loop
    for team_row in select distinct tp.team_id from public.team_players tp where tp.club_id=p_club_id and tp.player_id=p_player_id loop
      select amount into rate_value from public.team_dues_rates where club_id=p_club_id and team_id=team_row.team_id and effective_month <= cursor_month order by effective_month desc limit 1;
      if rate_value is not null and rate_value > 0 and not exists(select 1 from public.team_dues_entries where team_id=team_row.team_id and player_id=p_player_id and month=cursor_month) then insert into public.team_dues_entries(club_id,team_id,player_id,month,status,amount,finance_transaction_id,created_by) values(p_club_id,team_row.team_id,p_player_id,cursor_month,p_status,rate_value,tx_id,auth.uid()); end if;
    end loop;
    cursor_month := (cursor_month + interval '1 month')::date; n := n + 1;
  end loop;
  return jsonb_build_object('player_id',p_player_id,'months',p_months,'status',p_status,'amount',total_amount,'transaction_id',tx_id);
end $$;

create or replace function public.correct_team_dues(p_club_id bigint,p_team_id bigint,p_player_id bigint,p_month date,p_expected_status text,p_status text,p_reason text) returns jsonb language plpgsql security definer set search_path = public as $$
declare entry public.team_dues_entries; old_status text; amount_value numeric; old_tx bigint; new_tx bigint;
begin
  if not public.can_manage_finance(p_club_id) or p_expected_status not in ('unpaid','paid','exempt') or p_status not in ('unpaid','paid','exempt') or p_expected_status=p_status then raise exception 'invalid_correction'; end if;
  perform 1 from public.clubs where id=p_club_id and status='active' for update;
  select * into entry from public.team_dues_entries where club_id=p_club_id and team_id=p_team_id and player_id=p_player_id and month=date_trunc('month',p_month)::date for update;
  old_status := coalesce(entry.status,'unpaid'); if old_status <> p_expected_status then raise exception 'stale_dues_status'; end if;
  amount_value := coalesce(entry.amount,(select amount from public.team_dues_rates where club_id=p_club_id and team_id=p_team_id and effective_month <= p_month order by effective_month desc limit 1)); if coalesce(amount_value,0)=0 then raise exception 'no_dues_amount'; end if;
  old_tx := entry.finance_transaction_id;
  if old_status='paid' and old_tx is not null then update public.finance_transactions set amount=amount-amount_value where club_id=p_club_id and id=old_tx and type='income' and amount>=amount_value; if not found then raise exception 'missing_source_transaction'; end if; end if;
  if p_status='paid' then insert into public.finance_transactions(club_id,created_by,type,amount,occurred_on,description) values(p_club_id,auth.uid(),'income',amount_value,current_date,'Điều chỉnh thu quỹ '||p_player_id) returning id into new_tx; end if;
  delete from public.team_dues_entries where id=entry.id;
  if p_status <> 'unpaid' then insert into public.team_dues_entries(club_id,team_id,player_id,month,status,amount,finance_transaction_id,created_by) values(p_club_id,p_team_id,p_player_id,date_trunc('month',p_month)::date,p_status,amount_value,new_tx,auth.uid()); end if;
  insert into public.team_dues_adjustments(club_id,team_id,player_id,month,old_status,new_status,amount,old_transaction_id,new_transaction_id,reason,created_by) values(p_club_id,p_team_id,p_player_id,date_trunc('month',p_month)::date,old_status,p_status,amount_value,old_tx,new_tx,trim(p_reason),auth.uid());
  return jsonb_build_object('old_status',old_status,'new_status',p_status,'amount',amount_value);
end $$;

create or replace function public.sync_team_players(p_club_id bigint,p_team_id bigint,p_player_ids bigint[]) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.can_manage_roster(p_club_id) then raise exception 'forbidden'; end if;
  perform 1 from public.teams where club_id=p_club_id and id=p_team_id for update;
  if exists(select 1 from unnest(p_player_ids) requested where not exists(select 1 from public.player_profiles p where p.club_id=p_club_id and p.id=requested)) then raise exception 'invalid_player'; end if;
  update public.team_membership_periods set left_on=current_date, updated_at=now() where club_id=p_club_id and team_id=p_team_id and left_on is null and not (player_id=any(p_player_ids));
  delete from public.team_players where club_id=p_club_id and team_id=p_team_id and not (player_id=any(p_player_ids));
  insert into public.team_players(club_id,team_id,player_id) select p_club_id,p_team_id,p from unnest(p_player_ids) p on conflict(team_id,player_id) do nothing;
  insert into public.team_membership_periods(club_id,team_id,player_id,joined_on) select p_club_id,p_team_id,p,current_date from unnest(p_player_ids) p where not exists(select 1 from public.team_membership_periods x where x.club_id=p_club_id and x.team_id=p_team_id and x.player_id=p and x.left_on is null);
end $$;

create or replace function public.set_player_primary_team(p_club_id bigint,p_player_id bigint,p_team_id bigint) returns public.player_profiles language plpgsql security definer set search_path = public as $$
declare row_value public.player_profiles;
begin
  if not public.can_manage_roster(p_club_id) then raise exception 'forbidden'; end if;
  select * into row_value from public.player_profiles where club_id=p_club_id and id=p_player_id for update;
  if row_value.id is null or (p_team_id is not null and not exists(select 1 from public.teams where club_id=p_club_id and id=p_team_id)) then raise exception 'invalid_player_or_team'; end if;
  if p_team_id is not null then insert into public.team_players(club_id,team_id,player_id,jersey_number,position) values(p_club_id,p_team_id,p_player_id,row_value.jersey_number,row_value.position) on conflict(team_id,player_id) do nothing; end if;
  update public.team_membership_periods set left_on=current_date,updated_at=now() where club_id=p_club_id and player_id=p_player_id and left_on is null and (p_team_id is null or team_id<>p_team_id);
  delete from public.team_players where club_id=p_club_id and player_id=p_player_id and (p_team_id is null or team_id<>p_team_id);
  update public.player_profiles set team_id=p_team_id,current_jersey=case when p_team_id is null or status='inactive' then null else jersey_number end where club_id=p_club_id and id=p_player_id returning * into row_value;
  return row_value;
end $$;

create or replace function public.set_team_player_attribute(p_club_id bigint,p_team_id bigint,p_player_id bigint,p_attribute text,p_value text) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.can_manage_roster(p_club_id) then raise exception 'forbidden'; end if;
  if not exists(select 1 from public.team_players where club_id=p_club_id and team_id=p_team_id and player_id=p_player_id) then raise exception 'not_team_player'; end if;
  if p_attribute='position' then update public.team_players set position=nullif(trim(p_value),'') where club_id=p_club_id and team_id=p_team_id and player_id=p_player_id;
  elsif p_attribute='jersey_number' then update public.team_players set jersey_number=nullif(trim(p_value),'')::smallint where club_id=p_club_id and team_id=p_team_id and player_id=p_player_id;
  else raise exception 'invalid_attribute'; end if;
end $$;

create or replace function public.create_match_cost_split(p_club_id bigint,p_match_id bigint,p_stadium numeric,p_referee numeric,p_water numeric,p_equipment numeric,p_other numeric,p_sponsorship numeric,p_method text,p_players jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare split_row public.match_cost_splits; match_team_id bigint; total_amount numeric := coalesce(p_stadium,0)+coalesce(p_referee,0)+coalesce(p_water,0)+coalesce(p_equipment,0)+coalesce(p_other,0)-coalesce(p_sponsorship,0); player_row jsonb;
begin
  if not public.can_manage_roster(p_club_id) then raise exception 'forbidden'; end if;
  if total_amount < 0 or p_method not in ('equal','weighted','custom') then raise exception 'invalid_cost_split'; end if;
  select team_id into match_team_id from public.club_matches where club_id=p_club_id and id=p_match_id for update;
  if not found then raise exception 'match_not_found'; end if;
  if exists(select 1 from public.match_cost_splits where club_id=p_club_id and match_id=p_match_id) then raise exception 'cost_split_exists'; end if;
  insert into public.match_cost_splits(club_id,match_id,stadium,referee,water,equipment,other,sponsorship,total,method,payload_hash,created_by) values(p_club_id,p_match_id,coalesce(p_stadium,0),coalesce(p_referee,0),coalesce(p_water,0),coalesce(p_equipment,0),coalesce(p_other,0),coalesce(p_sponsorship,0),total_amount,p_method,encode(extensions.digest(coalesce(p_players,'[]'::jsonb)::text,'sha256'),'hex'),auth.uid()) returning * into split_row;
  for player_row in select value from jsonb_array_elements(coalesce(p_players,'[]'::jsonb)) loop
    if not exists(select 1 from public.player_profiles p where p.club_id=p_club_id and p.id=(player_row->>'player_id')::bigint and (exists(select 1 from public.team_players tp where tp.club_id=p_club_id and tp.team_id=match_team_id and tp.player_id=p.id) or exists(select 1 from public.match_attendances ma where ma.club_id=p_club_id and ma.match_id=p_match_id and ma.player_id=p.id))) then raise exception 'invalid_receivable_player'; end if;
    insert into public.match_cost_receivables(club_id,split_id,player_id,amount,exempt,weight) values(p_club_id,split_row.id,(player_row->>'player_id')::bigint,coalesce((player_row->>'amount')::bigint,0),coalesce((player_row->>'exempt')::boolean,false),coalesce((player_row->>'weight')::integer,1));
  end loop;
  return jsonb_build_object('split',to_jsonb(split_row));
end $$;

create or replace function public.assign_inventory(p_club_id bigint,p_item_id bigint,p_player_id bigint,p_quantity integer,p_reason text) returns jsonb language plpgsql security definer set search_path = public as $$
declare item public.inventory_items; player_row public.player_profiles; assignment_id bigint; next_balance integer;
begin
  if not public.can_manage_inventory(p_club_id) or p_quantity < 1 then raise exception 'forbidden_or_invalid'; end if;
  select * into item from public.inventory_items where club_id=p_club_id and id=p_item_id and archived=false for update;
  select * into player_row from public.player_profiles where club_id=p_club_id and id=p_player_id for update;
  if item.id is null or player_row.id is null or item.kind <> 'asset' then raise exception 'invalid_assignment'; end if;
  if item.quantity < p_quantity then raise exception 'insufficient_inventory'; end if;
  next_balance := item.quantity-p_quantity;
  insert into public.inventory_assignments(club_id,inventory_item_id,player_id,player_name,quantity,remaining,actor_id) values(p_club_id,p_item_id,p_player_id,player_row.full_name,p_quantity,p_quantity,auth.uid()) returning id into assignment_id;
  update public.inventory_items set quantity=next_balance where club_id=p_club_id and id=p_item_id;
  insert into public.inventory_movements(club_id,inventory_item_id,inventory_assignment_id,actor_id,type,change,balance_after,reason) values(p_club_id,p_item_id,assignment_id,auth.uid(),'assign',-p_quantity,next_balance,trim(p_reason));
  return jsonb_build_object('id',assignment_id,'quantity',next_balance);
end $$;

create or replace function public.return_inventory_assignment(p_club_id bigint,p_item_id bigint,p_assignment_id bigint,p_quantity integer,p_reason text) returns jsonb language plpgsql security definer set search_path = public as $$
declare item public.inventory_items; loan public.inventory_assignments; next_balance integer; next_remaining integer;
begin
  if not public.can_manage_inventory(p_club_id) or p_quantity < 1 then raise exception 'forbidden_or_invalid'; end if;
  select * into item from public.inventory_items where club_id=p_club_id and id=p_item_id and archived=false for update;
  select * into loan from public.inventory_assignments where club_id=p_club_id and inventory_item_id=p_item_id and id=p_assignment_id for update;
  if item.id is null or loan.id is null or loan.remaining < p_quantity then raise exception 'invalid_return'; end if;
  next_balance := item.quantity+p_quantity; next_remaining := loan.remaining-p_quantity;
  update public.inventory_assignments set remaining=next_remaining where id=loan.id;
  update public.inventory_items set quantity=next_balance where club_id=p_club_id and id=p_item_id;
  insert into public.inventory_movements(club_id,inventory_item_id,inventory_assignment_id,actor_id,type,change,balance_after,reason) values(p_club_id,p_item_id,p_assignment_id,auth.uid(),'return',p_quantity,next_balance,trim(p_reason));
  return jsonb_build_object('quantity',next_balance,'remaining',next_remaining);
end $$;

create or replace function public.update_inventory_item(p_club_id bigint,p_item_id bigint,p_name text,p_category text,p_unit text,p_kind text,p_low_stock_threshold integer,p_notes text) returns public.inventory_items language plpgsql security definer set search_path = public as $$
declare row_value public.inventory_items;
begin
  if not public.can_manage_inventory(p_club_id) or p_low_stock_threshold < 0 or p_kind not in ('consumable','asset') then raise exception 'forbidden_or_invalid'; end if;
  update public.inventory_items set name=trim(p_name),category=p_category,unit=trim(p_unit),kind=p_kind,low_stock_threshold=p_low_stock_threshold,notes=p_notes where club_id=p_club_id and id=p_item_id and archived=false returning * into row_value;
  if row_value.id is null then raise exception 'inventory_item_not_found'; end if; return row_value;
end $$;

create or replace function public.archive_inventory_item(p_club_id bigint,p_item_id bigint) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.can_manage_inventory(p_club_id) then raise exception 'forbidden'; end if;
  if exists(select 1 from public.inventory_items where club_id=p_club_id and id=p_item_id and quantity<>0) or exists(select 1 from public.inventory_assignments where club_id=p_club_id and inventory_item_id=p_item_id and remaining>0) then raise exception 'inventory_not_empty'; end if;
  update public.inventory_items set archived=true where club_id=p_club_id and id=p_item_id and archived=false;
end $$;

create or replace function public.restore_inventory_item(p_club_id bigint,p_item_id bigint) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.can_manage_inventory(p_club_id) then raise exception 'forbidden'; end if;
  update public.inventory_items set archived=false where club_id=p_club_id and id=p_item_id and archived=true;
end $$;

create or replace function public.save_planned_expense(p_club_id bigint,p_id bigint,p_description text,p_amount numeric,p_notes text,p_effective_from date,p_effective_to date) returns public.planned_expenses language plpgsql security definer set search_path = public as $$
declare row_value public.planned_expenses;
begin
  if not public.can_manage_finance(p_club_id) or coalesce(trim(p_description),'')='' or coalesce(p_amount,0) < 0 then raise exception 'forbidden_or_invalid'; end if;
  if p_id is null then insert into public.planned_expenses(club_id,created_by,description,amount,notes,effective_from,effective_to) values(p_club_id,auth.uid(),trim(p_description),p_amount,p_notes,p_effective_from,p_effective_to) returning * into row_value;
  else update public.planned_expenses set description=trim(p_description),amount=p_amount,notes=p_notes,effective_from=p_effective_from,effective_to=p_effective_to where club_id=p_club_id and id=p_id and cancelled=false returning * into row_value; end if;
  if row_value.id is null then raise exception 'planned_expense_not_found'; end if; return row_value;
end $$;

create or replace function public.cancel_planned_expense(p_club_id bigint,p_id bigint,p_effective_to date) returns public.planned_expenses language plpgsql security definer set search_path = public as $$
declare row_value public.planned_expenses;
begin
  if not public.can_manage_finance(p_club_id) then raise exception 'forbidden'; end if;
  update public.planned_expenses set cancelled=true,effective_to=coalesce(p_effective_to,effective_to) where club_id=p_club_id and id=p_id and cancelled=false returning * into row_value;
  if row_value.id is null then raise exception 'planned_expense_not_found'; end if; return row_value;
end $$;

create or replace function public.create_club_poll(p_club_id bigint,p_title text,p_description text,p_deadline timestamptz,p_options jsonb) returns public.club_polls language plpgsql security definer set search_path = public as $$
declare poll_row public.club_polls; option_row jsonb; position integer := 0; member_row record;
begin
  if not public.can_manage_roster(p_club_id) or coalesce(trim(p_title),'')='' or p_deadline <= now() or jsonb_array_length(coalesce(p_options,'[]'::jsonb)) < 2 then raise exception 'forbidden_or_invalid'; end if;
  insert into public.club_polls(club_id,created_by,title,description,deadline) values(p_club_id,auth.uid(),trim(p_title),p_description,p_deadline) returning * into poll_row;
  for option_row in select value from jsonb_array_elements(p_options) loop insert into public.club_poll_options(club_id,poll_id,label,sort_order) values(p_club_id,poll_row.id,trim(option_row#>>'{}'),position); position := position+1; end loop;
  for member_row in select user_id from public.club_members where club_id=p_club_id and status='active' loop insert into public.club_poll_electors(club_id,poll_id,user_id) values(p_club_id,poll_row.id,member_row.user_id); end loop;
  return poll_row;
end $$;

create or replace function public.cast_club_poll_vote(p_club_id bigint,p_poll_id bigint,p_option_id bigint) returns public.club_poll_votes language plpgsql security definer set search_path = public as $$
declare vote_row public.club_poll_votes;
begin
  if not exists(select 1 from public.club_poll_electors where club_id=p_club_id and poll_id=p_poll_id and user_id=auth.uid()) then raise exception 'not_eligible'; end if;
  if exists(select 1 from public.club_poll_votes where club_id=p_club_id and poll_id=p_poll_id and user_id=auth.uid()) then raise exception 'already_voted'; end if;
  if not exists(select 1 from public.club_poll_options o join public.club_polls p on p.club_id=o.club_id and p.id=o.poll_id where o.club_id=p_club_id and o.poll_id=p_poll_id and o.id=p_option_id and p.deadline > now()) then raise exception 'invalid_poll_option'; end if;
  insert into public.club_poll_votes(club_id,poll_id,user_id,option_id) values(p_club_id,p_poll_id,auth.uid(),p_option_id) returning * into vote_row; return vote_row;
end $$;

create or replace function public.delete_player_match_stat(p_club_id bigint,p_match_id bigint,p_player_id bigint) returns void language plpgsql security definer set search_path = public as $$
begin
  if not public.can_manage_roster(p_club_id) then raise exception 'forbidden'; end if;
  delete from public.player_match_stats where club_id=p_club_id and match_id=p_match_id and player_id=p_player_id;
end $$;

create or replace function public.create_friendly_invitation(p_source_club_id bigint,p_target_club_id bigint,p_match_date date,p_match_time text,p_location text,p_message text) returns public.friendly_invitations language plpgsql security definer set search_path = public as $$
declare row_value public.friendly_invitations; low_id bigint; high_id bigint; pair text;
begin
  if not public.can_manage_club(p_source_club_id) or p_source_club_id=p_target_club_id or p_match_date < current_date then raise exception 'forbidden_or_invalid'; end if;
  if p_source_club_id < p_target_club_id then low_id:=p_source_club_id; high_id:=p_target_club_id; else low_id:=p_target_club_id; high_id:=p_source_club_id; end if; pair:=low_id||':'||high_id;
  perform 1 from public.clubs where id in (p_source_club_id,p_target_club_id) and status='active' for update;
  if (select count(*) from public.clubs where id in (p_source_club_id,p_target_club_id) and status='active') <> 2 or not exists(select 1 from public.clubs where id=p_target_club_id and is_discoverable) then raise exception 'target_club_not_available'; end if;
  if exists(select 1 from public.friendly_invitations where pair_key=pair and pending_key='pending') then raise exception 'pending_invitation_exists'; end if;
  insert into public.friendly_invitations(source_club_id,target_club_id,pair_key,pending_key,status,match_date,match_time,location,message,created_by) values(p_source_club_id,p_target_club_id,pair,'pending','pending',p_match_date,p_match_time,p_location,p_message,auth.uid()) returning * into row_value; return row_value;
end $$;

create or replace function public.respond_friendly_invitation(p_club_id bigint,p_invitation_id bigint,p_status text) returns void language plpgsql security definer set search_path = public as $$
declare row_value public.friendly_invitations;
begin
  if not public.can_manage_club(p_club_id) or p_status not in ('accepted','rejected','cancelled') then raise exception 'forbidden_or_invalid'; end if;
  select * into row_value from public.friendly_invitations where id=p_invitation_id and (source_club_id=p_club_id or target_club_id=p_club_id) for update;
  if row_value.id is null or row_value.status <> 'pending' or (p_status='cancelled' and row_value.source_club_id<>p_club_id) or (p_status<>'cancelled' and row_value.target_club_id<>p_club_id) then raise exception 'invalid_invitation_state'; end if;
  update public.friendly_invitations set status=p_status,pending_key=null,responded_by=auth.uid() where id=row_value.id;
end $$;

create or replace function public.commit_member_import(p_club_id bigint,p_rows jsonb,p_decisions jsonb) returns jsonb language plpgsql security definer set search_path = public as $$
declare row_value jsonb; decision jsonb; action text; target_id bigint; created_count integer:=0; overwritten_count integer:=0; skipped_count integer:=0;
begin
  if not public.can_manage_roster(p_club_id) or jsonb_array_length(p_rows) <> jsonb_array_length(p_decisions) or jsonb_array_length(p_rows)>500 then raise exception 'forbidden_or_invalid'; end if;
  for row_index in 0..jsonb_array_length(p_rows)-1 loop
    row_value:=p_rows->row_index; decision:=p_decisions->row_index; action:=decision->>'action'; target_id:=nullif(decision->>'target_id','')::bigint;
    if action='skip' then skipped_count:=skipped_count+1;
    elsif action='overwrite' then
      if target_id is null or not exists(select 1 from public.player_profiles where club_id=p_club_id and id=target_id) then raise exception 'invalid_import_target'; end if;
      update public.player_profiles set full_name=coalesce(row_value->>'full_name',full_name),email=nullif(lower(row_value->>'email'),''),phone=nullif(row_value->>'phone',''),date_of_birth=nullif(row_value->>'date_of_birth','')::date,position=nullif(row_value->>'position',''),preferred_foot=nullif(row_value->>'preferred_foot',''),status=coalesce(nullif(row_value->>'status',''),status::text)::public.player_status,notes=nullif(row_value->>'notes','') where club_id=p_club_id and id=target_id; overwritten_count:=overwritten_count+1;
    elsif action='create' then
      insert into public.player_profiles(club_id,full_name,email,phone,date_of_birth,position,preferred_foot,status,notes) values(p_club_id,row_value->>'full_name',nullif(lower(row_value->>'email'),''),nullif(row_value->>'phone',''),nullif(row_value->>'date_of_birth','')::date,nullif(row_value->>'position',''),nullif(row_value->>'preferred_foot',''),coalesce(nullif(row_value->>'status',''),'active')::public.player_status,nullif(row_value->>'notes','')); created_count:=created_count+1;
    else raise exception 'invalid_import_decision'; end if;
  end loop;
  return jsonb_build_object('created',created_count,'overwritten',overwritten_count,'skipped',skipped_count);
end $$;

create or replace function public.create_discipline_case(p_club_id bigint,p_player_id bigint,p_incident_date date,p_title text,p_description text,p_status text,p_decision text,p_fine_amount numeric) returns public.discipline_cases language plpgsql security definer set search_path = public as $$
declare row_value public.discipline_cases;
begin
  if not public.can_manage_people(p_club_id) or not exists(select 1 from public.player_profiles where club_id=p_club_id and id=p_player_id) then raise exception 'forbidden_or_invalid'; end if;
  insert into public.discipline_cases(club_id,player_id,incident_date,title,description,status,decision,fine_amount,created_by) values(p_club_id,p_player_id,p_incident_date,p_title,p_description,p_status,p_decision,p_fine_amount,auth.uid()) returning * into row_value;
  insert into public.discipline_case_history(club_id,case_id,actor_id,action,snapshot) values(p_club_id,row_value.id,auth.uid(),'created',to_jsonb(row_value)); return row_value;
end $$;

create or replace function public.update_discipline_case(p_club_id bigint,p_case_id bigint,p_player_id bigint,p_incident_date date,p_title text,p_description text,p_status text,p_decision text,p_fine_amount numeric,p_reason text) returns void language plpgsql security definer set search_path = public as $$
declare row_value public.discipline_cases;
begin
  if not public.can_manage_people(p_club_id) or not exists(select 1 from public.player_profiles where club_id=p_club_id and id=p_player_id) then raise exception 'forbidden_or_invalid'; end if;
  update public.discipline_cases set player_id=p_player_id,incident_date=p_incident_date,title=p_title,description=p_description,status=p_status,decision=p_decision,fine_amount=p_fine_amount where club_id=p_club_id and id=p_case_id returning * into row_value;
  if row_value.id is null then raise exception 'case_not_found'; end if;
  insert into public.discipline_case_history(club_id,case_id,actor_id,action,reason,snapshot) values(p_club_id,p_case_id,auth.uid(),'updated',p_reason,to_jsonb(row_value));
end $$;

alter table public.profiles enable row level security;
create policy profiles_self_select on public.profiles for select to authenticated using (id=auth.uid());
create policy profiles_self_update on public.profiles for update to authenticated using (id=auth.uid()) with check (id=auth.uid());
create policy profiles_self_insert on public.profiles for insert to authenticated with check (id=auth.uid());

do $$ declare t text; begin foreach t in array array['clubs','club_members','teams','player_profiles','club_invitations','audit_logs','team_managers','team_players','finance_transactions','team_dues_rates','team_membership_periods','team_dues_entries','team_dues_adjustments','club_board_members','board_membership_periods','board_dues_rates','shared_board_dues_rates','club_celebrations','team_trainings','club_awards','planned_expenses','friendly_invitations','club_matches','match_lineups','match_attendances','player_match_stats','match_cost_splits','match_cost_receivables','inventory_items','inventory_assignments','inventory_movements','club_polls','club_poll_options','club_poll_electors','club_poll_votes','recruitment_posts','recruitment_applications','sponsors','sponsorships','sponsorship_receipts','discipline_cases','discipline_case_history','board_tasks','seasons','club_events','notifications','funds','financial_periods','transaction_approvals','payments','payment_allocations','import_jobs','club_public_settings'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;

create policy clubs_member_select on public.clubs for select to authenticated using ((status='active' and public.is_active_member(id)) or (status='active' and is_discoverable));
create policy clubs_create on public.clubs for insert to authenticated with check (false);
create policy clubs_manager_update on public.clubs for update to authenticated using (public.can_manage_club(id)) with check (public.can_manage_club(id));
create policy clubs_owner_delete on public.clubs for delete to authenticated using (public.club_role(id)='owner');

