insert into storage.buckets(id,name,public) values('fcms-private','fcms-private',false) on conflict (id) do update set public=false;
create policy fcms_private_objects_read on storage.objects for select to authenticated using (
  bucket_id='fcms-private' and (
    name like 'accounts/'||auth.uid()::text||'/%' or
    (name like 'clubs/%' and (public.is_active_member(nullif(substring(name from '^clubs/([0-9]+)/'),'')::bigint) or exists(select 1 from public.clubs c where c.id=nullif(substring(name from '^clubs/([0-9]+)/'),'')::bigint and c.is_discoverable and c.status='active'))) or
    (name like 'players/%' and public.is_active_member(nullif(substring(name from '^players/([0-9]+)/'),'')::bigint)) or
    (name like 'finance/%' and public.can_view_finance(nullif(substring(name from '^finance/([0-9]+)/'),'')::bigint))
  )
);
create policy fcms_private_objects_insert on storage.objects for insert to authenticated with check (
  bucket_id='fcms-private' and (
    name like 'accounts/'||auth.uid()::text||'/%' or
    (name like 'clubs/%' and public.can_manage_club(nullif(substring(name from '^clubs/([0-9]+)/'),'')::bigint)) or
    (name like 'players/%' and public.can_manage_roster(nullif(substring(name from '^players/([0-9]+)/'),'')::bigint)) or
    (name like 'finance/%' and public.can_manage_finance(nullif(substring(name from '^finance/([0-9]+)/'),'')::bigint))
  )
);
create policy fcms_private_objects_update on storage.objects for update to authenticated using (bucket_id='fcms-private' and owner_id=auth.uid()::text) with check (bucket_id='fcms-private' and owner_id=auth.uid()::text);
create policy fcms_private_objects_delete on storage.objects for delete to authenticated using (bucket_id='fcms-private' and owner_id=auth.uid()::text);

